function R=SMPV_P0_RECORD(module,K,M,A,model,metrics,version,budget,signature,initSeconds,totalSeconds,scientific)
    R=struct('Module',module,'Dataset',K.Dataset,'Condition',K.Condition,'Type',K.Type, ...
        'NominalRate',K.NominalRate,'ActualRate',mean(K.mask(:)),'Strength',K.Strength, ...
        'Repeat',K.Repeat,'Seed',K.Seed,'MethodID',M.id,'Method',M.name,'SolverVersion',version, ...
        'BudgetMultiplier',budget,'OuterCap',A.maxOuter,'InnerCap',A.maxInner, ...
        'ProposalBacktrackCap',A.mmLineSearchMax,'TimeCapSeconds',A.maxTimePerMethod, ...
        'IsScientificRun',scientific,'CaseHash',K.caseHash,'InitHash',K.initHash,'FitSignature',signature, ...
        'Status',model.status,'StopReason',model.StopReason, ...
        'AcceptedSteps',model.AcceptedSteps,'GradientAcceptedSteps',get(model,'GradientAcceptedSteps',NaN), ...
        'LastAttemptAccepted',model.LastAttemptAccepted,'OuterIters',model.outerIters, ...
        'SolverSeconds',model.TimeSeconds,'InitializationSeconds',initSeconds,'TotalSeconds',totalSeconds, ...
        'Tau',model.finalTau,'Eta',model.finalEta,'Guard',model.finalGuard, ...
        'CurrentSeverity',model.finalCurrentTailSeverity,'HistoricalSeverity',model.finalTailSeverity, ...
        'FinalRecomputedGradRelative',get(model,'FinalRecomputedGradRelative',NaN), ...
        'LastFrozenGradRelative',get(model,'LastFrozenGradRelative',NaN), ...
        'ConditionalChecks',model.ConditionalChecks,'ConditionalViolations',model.ConditionalViolations, ...
        'AcceptedConditionalChecks',get(model,'AcceptedConditionalChecks',model.ConditionalChecks), ...
        'LWouldVetoCount',get(model,'LWouldVetoCount',NaN), ...
        'AcceptedStepsWithLossVeto',get(model,'AcceptedStepsWithLossVeto',0), ...
        'AcceptedQViolations',get(model,'AcceptedQViolations',NaN), ...
        'GradientTolerance',A.gradientTolerance, ...
        'ConditionalCheckScope','');
    if strcmp(version,'v2'),R.ConditionalCheckScope='all_finite_trials_all_branches';
    else,R.ConditionalCheckScope='accepted_nonguard_tukey_trials';end
    f=fieldnames(model.finalDiagnostics);
    for j=1:numel(f)
        if ~strcmp(f{j},'perImage'),R.(f{j})=model.finalDiagnostics.(f{j});end
    end
    if isempty(model.lastUsedDiagnostics),R.LastUsedZeroExact=NaN;
    else,R.LastUsedZeroExact=model.lastUsedDiagnostics.ZeroExact;end
    f=fieldnames(metrics);for j=1:numel(f),R.(f{j})=metrics.(f{j});end
end

function v=get(s,name,default)
    if isfield(s,name),v=s.(name);else,v=default;end
end
